  [Serializable]public sealed class SeedReport{public int seed;public string beganUtc,endedUtc,metadataStart,actualPlacementStart,cohortSha256,error;public int cachedBeforeFreeze,cachedAfterFreeze;public bool placementMatched,complete;public QuestFreeCohort.Plan cohort;public List<ZoneRow> rows=new List<ZoneRow>();public string boundary="Native core source census only. ObservedManager uses the normal activating constructor inside the accepted fixture scope; it is not a detached manager. Exact fixture and outer registry restoration run afterward. No Play/input/render/visibility/awareness or human decisions. RNG is explicitly seeded once per seed and then advances in frozen BFS generation order; this is not normal global-RNG replay or visitation-order determinism. FreshGameStart policy placement is tested with a factory Player, not a full ordinary bootstrap. No actor turns, GetInventoryActions callbacks, stock transfers or reward grants.";}
